"""本地业务页面交互。"""

def detail_fragment(item):
    return "<select id=\"category\"><option>手作</option><option>食饮</option></select><input id=\"attachment\" type=\"file\"><button id=\"draft\">保存演练草稿</button><output id=\"draft-state\"></output><button id=\"confirm\">查看确认页</button><output id=\"confirmation\"></output><script>let category=document.querySelector('#category'),attachment=document.querySelector('#attachment'),status=document.querySelector('#draft-state'),confirm=document.querySelector('#confirmation');const draftKey='stall-draft:'+document.querySelector('main').dataset.key;let version=0;const restored=JSON.parse(sessionStorage.getItem(draftKey)||'null');if(restored){category.value=restored.category;status.textContent='草稿已恢复；材料需重新附上并核对';version=restored.version;}category.onchange=()=>{version++;attachment.value='';status.textContent='材料待核对';confirm.textContent=''};attachment.onchange=()=>{version++;status.textContent=attachment.files.length?'已预览：'+attachment.files[0].name:'材料待核对';confirm.textContent=''};document.querySelector('#draft').onclick=()=>{sessionStorage.setItem(draftKey,JSON.stringify({category:category.value,filename:attachment.files[0]?.name||null,version}));status.textContent='草稿：'+category.value+' / v'+version};document.querySelector('#confirm').onclick=()=>{let draft=JSON.parse(sessionStorage.getItem(draftKey)||'null');confirm.textContent=draft?.version===version?'待人工确认 / v'+version:'草稿已变化'};</script>"

def source_extension(item):
    return """<output id="upload-digest"></output><output id="draft-check"></output><script>(()=>{
let digest=document.querySelector('#upload-digest'),attachment=document.querySelector('#attachment'),check=document.querySelector('#draft-check'),category=document.querySelector('#category');const draftKey='stall-draft:'+document.querySelector('main').dataset.key;
attachment.addEventListener('change',async()=>{let file=attachment.files[0];if(!file){digest.textContent='';return}let bytes=await file.arrayBuffer(),hash=await crypto.subtle.digest('SHA-256',bytes);digest.textContent='附件摘要：'+Array.from(new Uint8Array(hash)).map(value=>value.toString(16).padStart(2,'0')).join('');check.textContent='';});
category.addEventListener('change',()=>{digest.textContent='';check.textContent='';});
document.querySelector('#draft').addEventListener('click',()=>{let stored=JSON.parse(sessionStorage.getItem(draftKey)||'null');if(stored){stored.digest=digest.textContent;sessionStorage.setItem(draftKey,JSON.stringify(stored));check.textContent=stored.category+' / '+stored.filename+' / '+stored.digest;}});
document.querySelector('#confirm').addEventListener('click',()=>{let stored=JSON.parse(sessionStorage.getItem(draftKey)||'null');check.textContent=stored?.category===category.value && stored?.digest===digest.textContent?stored.category+'：材料摘要已核':'材料版本待核对';});
})();</script>"""
